    {
      "label": "QUOTE",
      "head": "གང་ཡང་ཡོངས་สུ་མྱ་ངན་",
      "tail": "མྱ་ངན་ལས་འདའ་བའི་རིགས་ཉིད་མེད་པའོ་ཞེས་པས་འགྲུབ་བོ། །"
    },
    {
      "label": "QUOTE",
      "head": "ཡོད་དང་མཆོག་དང་མཚན་ཉིད་",
      "tail": "པར་བསྟན་པ། ཐེག་པ་ཆེན་པོའི་རིགས་མཆོག་ཏུ་སྒྲུབ་པ། རིགས་ཀྱི་མཚན་ཉིད། རིགས་སད་པའི་རྟགས། རིགས་ཀྱི་རབ་དབྱེ། རིགས་ཁྱད་པར་དུ་འགྱུར་བ་ལ་བར་དུ་གཅོད་པའི་ཉེས་དམིགས། རིགས་སད་པའི་ཕན་ཡོན། ཐུན་མོང་གི་ཡོན་ཏན་སྐྱེད་པར་གསེར་གྱི་དཔེས་བསྟན་པ། ཐུན་མོང་མིན་པའི་ཡོན་ཏན་སྐྱེད་པ་རིན་པོ་ཆེའི་དཔེས་བསྟན་པ་དང་དགུ་ལས། དེ་རེ་རེའང་དོན་ཚན་བཞི་བཞིའི་སྒོ་ནས་གཏན་ལ་དབབ་པའོ། །དེ་ལ་དང་པོ་ནི། སེམས་ཅན་རྣམས་ལ་ཐེག་པ་གསུམ་གྱི་རིགས་ཐ་དད་པ་སོ་སོར་ཡོད་དེ། སེམས་ཅན་རྣམས་ཁམས་སྣ་ཚོགས་པ་ཅན་དུ་གསུངས་པའི་ཕྱིར་དང་། དང་པོར་ཐེག་པ་གསུམ་གྱི་མོས་པ་ཐ་དད། བར་དུ་སྒྲུབ་པ་ཐ་དད། ཐ་མར་འབྲས་བུ་ཐ་དད་དུ་དམིགས་པའི་ཕྱིར། གཉིས་པ་ནི། དེ་རྣམས་ཀྱི་ནང་ནས་ཐེག་པ་ཆེན་པོའི་རིགས་མཆོག་ཡིན་ཏེ། སྒྲིབ་གཉིས་སྤོང་བའི་དགེ་བའི་རྒྱུ་བྱེད་པ་དང་། སྟོབས་སོགས་ཡོན་ཏན་ཐམས་ཅད་ཀྱི་རྒྱུ་བྱེད་པའི་ཕྱིར་དང་། རང་བཞིན་གྱི་དོན་ཆེན་པོའི་རྒྱུ་བྱེད་པ་དང་། ལྷག་མེད་ཀྱི་སྐབས་སུའང་དགེ་བའི་རྩ་བ་མི་ཟད་པའི་རྒྱུ་བྱེད་པའི་ཕྱིར། གསུམ་པ་ནི། རང་བཞིན་དང་ནི་རྒྱས་པ་དང་། །ཞེས་པས་མཚན་བྱ་བསྟན། དེ་ནི་རྟེན་དང་བརྟེན་པ་དང་། །ཡོད་མེད་ཉིད། །ཅེས་པས་མཚན་ཉིད་བསྟན། ཡོན་ཏན་ནི། སྒྲོལ་བའི་དོན་དུ་ཤེས་པར་བྱ། །ཞེས་པའི་སྒྲ་དོན་བསྟན་ནོ། །རང་བཞིན་གནས་རིགས་ཀྱི་མཚན་ཉིད། རང་ལ་བརྟེན་པའི་ཡོན་ཏན་གྱི་རྟེན་བྱེད་ཅིང་། རྒྱུའི་ངོ་བོར་ཡོད། འབྲས་བུའི་ངོ་བོར་མེད་པའི་རིགས། རྒྱས་འགྱུར་གྱི་རིགས་ཀྱི་མཚན་ཉིད། རང་བཞིན་གནས་རིགས་ལ་བརྟེན་ནས་རྒྱུ་འབྲས་གཉིས་ཀའི་ངོ་བོར་ཡོད་པའི་རིགས། སྒྲ་དོན་ནི། རིགས་ཀྱི་སྐད་དོད་དུ་གུ་ཏྲ་ཞེས་འབྱུང་ལ། གུ་ལ་ཎ་སྦྱར་བས་གུ་ཎ་སྟེ་ཡོན་ཏན་དང་། །ཏ་དང་ར་ཕྲལ་བས་ཏ་ར་སྟེ་སྒྲོལ་བ་ལ་འཇུག་གོ །དེའང་ཡོན་ཏན་ལ་བརྟེན་ནས་སྲིད་པ་ལས་སྒྲོལ་བས་ན་ཡོན་ཏན་སྒྲོལ་ཞེས་བྱའོ། །བཞི་པ་ནི། ཐེག་ཆེན་གྱི་ལམ་ལ་སྦྱོར་བའི་སྔ་རོལ་དུ་ཡང་བསམ་པའི་ཡོན་ཏན་རང་བཞིན་གྱིས་སྙིང་རྗེ་ཆེ་བ། ཐེག་ཆེན་གྱི་ཆོས་ལ་མོས་པ། སྦྱོར་བའི་ཡོན་ཏན་གཞན་དོན་གྱི་དཀའ་སྤྱད་ལ་བསྲན་བཟོད་པ། སྦྱིན་སོགས་ཀྱི་དགེ་བ་ལ་ཡང་དག་པར་སྤྱོད་པའོ། །ལྔ་པ་ལ། རིགས་ངེས་པ་དང་མ་ངེས་པ་གཉིས། རྐྱེན་གྱིས་འཕྲོག་ནུས་པ་དང་མི་ནུས་པ་གཉིས། ཕྱི་མ་གཉིས་སྔ་མ་གཉིས་ཀྱི་དོན་ནོ། །དྲུག་པ་ནི། ཉོན་མོངས་པ་རྒྱུན་དུ་གོམས་པ་དང་། གྲོགས་ངན་པ་དང་འགྲོགས་པ་དང་། ལོངས་སྤྱོད་ཀྱིས་ཕོངས་པ་དང་། གཞན་གྱི་དབང་དུ་སོང་བའོ། །བདུན་པ་ནི། མི་དགེ་བ་ཅུང་ཟད་བྱས་པའི་སྟོབས་ཀྱི་ངན་སོང་དུ་འགྲོ་ནའང་རིང་མོ་ཞིག་ནས་འགྲོ་བ་དང་། དེ་ལས་མྱུར་དུ་ཐར་པ་དང་། དེར་སྡུག་བསྔལ་ཆུང་ངུ་མྱོང་བ་དང་། སྐྱོ་བ་དང་བཅས་པའི་སྒོ་ནས་སེམས་ཅན་སྨིན་པར་བྱེད་པའོ། །བརྒྱད་པ་ནི། ཐེག་ཆེན་གྱི་རིགས་དེ་གསེར་གྱི་འབྱུང་ཁུངས་དང་ཆོས་མཚུངས་ཏེ། དེ་ལས་གསེར་མང་པོ་དང་། འོད་གསལ་བ་དང་། གཡའ་ལ་སོགས་པའི་དྲི་མ་མེད་པ་དང་། ལས་སུ་རུང་བ་འབྱུང་བ་བཞིན་དུ། སྦྱིན་སོགས་ཀྱི་དགེ་བ་དཔག་དུ་མེད་པ་དང་། ཡེ་ཤེས་ཀྱི་རྟོག་པ་དང་། དྲི་མ་མེད་པའི་སྤངས་པ་དང་། མངོན་ཤེས་ལ་སོགས་པ་མཐུ་དཔག་ཏུ་མེད་པ་འབྱུང་བའི་གནས་ཡིན་པའི་ཕྱིར་རོ། །དགུ་པ་ནི། དེ་རིན་པོ་ཆེའི་འབྱུང་ཁུངས་དང་ཆོས་མཚུངས་ཏེ། དེ་ལས་རིན་པོ་ཆེའི་རིགས་དང་ལྡན་པ། ཁ་དོག་ཕུན་སུམ་ཚོགས་པ། དབྱིབས་ཕུན་སུམ་ཚོགས་པ། མཐུ་ཕུན་སུམ་ཚོགས་པ་འབྱུང་བ་བཞིན་དུ། བྱང་ཆུབ་ཆེན་པོ་དང་། མེ་ལོང་ལྟ་བུའི་ཡེ་ཤེས་ཆེན་པོ་དང་། དཔའ་བར་འགྲོ་བ་ལ་སོགས་པའི་ཏིང་ངེ་འཛིན་ཆེན་པོ་དང་། སེམས་ཅན་གྱི་དོན་མང་པོ་འབྱུང་བའི་གནས་ཡིན་པའི་ཕྱིར་རོ། །བཞི་པ་དབུ་མ་པའི་ལུགས་ལ། མཚན་གཞི། མཚན་ཉིད། དབྱེ་བ། རིགས་སུ་འགྱུར་ཚུལ་དང་བཞིའོ། །དང་པོ་ལ། ཁ་རག་པ་བྱང་ཆུབ་གཞོན་ནུ་ན་རེ། དྲི་མ་དང་བཅས་པའི་སེམས་རིག་ཅིང་གསལ་ཙམ་ཁོ་ན་རང་བཞིན་གནས་རིགས་ཡིན་གྱི། དེའི་ཆོས་ཉིད་ནི་དེ་མིན་ཏེ། གཞན་དུ་ན་ཆོས་ཉིད་ལ་རིགས་མི་འདྲ་བའི་དབྱེ་བ་མེད་པས། བུམ་སྣམ་སོགས་ཀྱི་ཆོས་ཉིད་ཀྱང་རང་བཞིན་གནས་རིགས་སུ་ཐལ་ལོ་ཞེས་གསུངས་སོ། །དེའི་སློབ་མ་བློ་གྲོས་མཚུངས་མེད་ན་རེ། དྲི་བཅས་ཀྱི་སེམས་དེ་རང་བཞིན་གནས་རིགས་ཡིན་ཏེ། ཀླུ་སྒྲུབ་ཀྱིས།"
    }
  ]
